<style>
    .ctw { --ctw-border:#e2e8f0; --ctw-bg:#fff; --ctw-soft:#f8fafc; --ctw-text:#0f172a; --ctw-muted:#64748b; --ctw-accent:#0284c7; color:var(--ctw-text); font-size:13px; }
    .dark .ctw { --ctw-border:#334155; --ctw-bg:#111827; --ctw-soft:#1e293b; --ctw-text:#f1f5f9; --ctw-muted:#94a3b8; --ctw-accent:#38bdf8; }
    .ctw [x-cloak] { display:none!important; }.ctw svg { width:20px; height:20px; flex-shrink:0; }.ctw button { cursor:pointer; }.ctw button:focus-visible,.ctw a:focus-visible,.ctw input:focus-visible { outline:2px solid var(--ctw-accent); outline-offset:3px; }
    .ctw-intro { display:flex; justify-content:space-between; align-items:center; gap:20px; margin-bottom:24px; }.ctw-intro p { color:var(--ctw-muted); line-height:1.7; margin-top:5px; max-width:630px; font-size:12px; }
    .ctw-eyebrow { color:var(--ctw-muted); font-size:10px; font-weight:650; text-transform:uppercase; letter-spacing:.08em; }.ctw-actions { display:flex; flex-wrap:wrap; align-items:center; gap:10px; flex-shrink:0; }
    .ctw-tabs { display:flex; gap:6px; border-bottom:1px solid var(--ctw-border); margin-bottom:24px; overflow-x:auto; }.ctw-tab { display:flex; align-items:center; gap:8px; padding:13px 15px; border-bottom:2px solid transparent; margin-bottom:-1px; color:var(--ctw-muted); font-size:12px; font-weight:600; white-space:nowrap; background:transparent; }.ctw-tab.is-active { color:var(--ctw-accent); border-color:var(--ctw-accent); }.ctw-tab:hover { background:var(--ctw-soft); }.ctw-tab svg { width:18px; height:18px; }
    .ctw-count { display:inline-flex; align-items:center; justify-content:center; min-width:23px; height:22px; border-radius:6px; background:var(--ctw-soft); color:var(--ctw-muted); padding:0 5px; font-size:10px; }.ctw-tab.is-active .ctw-count { color:var(--ctw-accent); background:color-mix(in srgb,var(--ctw-accent) 10%,var(--ctw-bg)); }
    .ctw-section-heading { display:flex; gap:16px; align-items:center; justify-content:space-between; margin-bottom:18px; }.ctw h2 { font-size:19px; font-weight:700; }.ctw-section-heading p { font-size:12px; color:var(--ctw-muted); margin-top:5px; line-height:1.7; max-width:650px; }
    .ctw-search { display:flex; align-items:center; gap:10px; padding:0 13px; background:var(--ctw-bg); border:1px solid var(--ctw-border); border-radius:10px; color:var(--ctw-muted); margin-bottom:20px; max-width:600px; }.ctw-search input { background:transparent; border:0; box-shadow:none!important; width:100%; min-width:0; padding:12px 0; font-size:12px; color:var(--ctw-text); }.ctw-search:focus-within { border-color:var(--ctw-accent); }
    .ctw-workspace { display:grid; grid-template-columns:minmax(240px,.8fr) minmax(0,1.6fr); border:1px solid var(--ctw-border); border-radius:14px; background:var(--ctw-bg); overflow:hidden; min-height:430px; }.ctw-list { background:var(--ctw-soft); border-right:1px solid var(--ctw-border); max-height:750px; overflow-y:auto; }.ctw-list-heading { display:flex; justify-content:space-between; gap:8px; padding:15px; border-bottom:1px solid var(--ctw-border); color:var(--ctw-muted); font-size:10px; }.ctw-list-heading span:first-child { font-weight:600; color:var(--ctw-text); }
    .ctw-list-item { width:100%; display:flex; align-items:center; text-align:left; gap:11px; padding:17px 15px; border-bottom:1px solid var(--ctw-border); border-left:3px solid transparent; background:transparent; }.ctw-list-item:hover { background:var(--ctw-bg); }.ctw-list-item.is-selected { background:var(--ctw-bg); border-left-color:var(--ctw-accent); }.ctw-list-item > svg { width:15px; height:15px; color:var(--ctw-muted); }
    .ctw-avatar { display:grid; place-items:center; width:36px; height:36px; border-radius:50%; flex-shrink:0; background:color-mix(in srgb,var(--ctw-accent) 10%,var(--ctw-bg)); color:var(--ctw-accent); font-size:14px; font-weight:650; }.ctw-avatar.is-large { width:52px; height:52px; font-size:21px; }.ctw-avatar.is-square { border-radius:10px; }
    .ctw-person-name { flex:1; min-width:0; }.ctw-person-name strong { display:block; font-size:12px; font-weight:650; overflow-wrap:anywhere; }.ctw-person-name small { display:block; font-size:10px; margin-top:3px; color:var(--ctw-muted); overflow-wrap:anywhere; }.ctw-person-name > span { display:block; font-size:10px; margin-top:6px; color:var(--ctw-muted); line-height:1.6; }
    .ctw-dot { width:7px; height:7px; border-radius:50%; background:#94a3b8; flex-shrink:0; }.ctw-dot.is-active { background:#10b981; }
    .ctw-detail { min-width:0; padding:25px; }.ctw-profile { display:flex; gap:14px; align-items:center; margin-bottom:23px; }.ctw h3 { font-size:19px; font-weight:700; overflow-wrap:anywhere; }.ctw-profile p { font-size:12px; color:var(--ctw-muted); margin-top:4px; overflow-wrap:anywhere; }
    .ctw-badges { display:flex; flex-wrap:wrap; gap:6px; margin-top:10px; }.ctw-badge { display:inline-flex; align-items:center; gap:4px; padding:4px 8px; border-radius:6px; font-size:10px; font-weight:550; }.ctw-badge.is-green { color:#047857; background:#ecfdf5; }.ctw-badge.is-blue { color:var(--ctw-accent); background:color-mix(in srgb,var(--ctw-accent) 9%,var(--ctw-bg)); }.ctw-badge.is-neutral { background:var(--ctw-soft); color:var(--ctw-muted); border:1px solid var(--ctw-border); }.dark .ctw-badge.is-green { color:#6ee7b7; background:#064e3b; }
    .ctw-notice { display:flex; align-items:start; gap:10px; border:1px solid var(--ctw-border); background:var(--ctw-soft); border-radius:10px; padding:14px; margin-bottom:20px; }.ctw-notice > svg { color:var(--ctw-accent); width:18px; height:18px; margin-top:1px; }.ctw-notice > div { flex:1; min-width:0; }.ctw-notice strong { font-size:11px; font-weight:650; }.ctw-notice p,.ctw-notice small { color:var(--ctw-muted); font-size:11px; line-height:1.7; margin-top:4px; }.ctw-notice.is-success { border-color:color-mix(in srgb,#10b981 35%,var(--ctw-border)); }.ctw-invitation-link { display:block; overflow-wrap:anywhere; color:var(--ctw-accent); font-size:11px; margin-top:6px; text-decoration:underline; }
    .ctw-outline-button { border:1px solid var(--ctw-border); border-radius:7px; padding:7px 10px; font-size:11px; background:var(--ctw-bg); white-space:nowrap; }
    .ctw-detail-heading { display:flex; align-items:start; justify-content:space-between; gap:15px; margin-bottom:16px; }.ctw-detail-heading h4,.ctw-subheading { font-size:12px; font-weight:650; }.ctw-detail-heading p { color:var(--ctw-muted); font-size:11px; margin-top:5px; line-height:1.7; }.ctw-subheading { margin:23px 0 12px; }
    .ctw-grant { border:1px solid var(--ctw-border); border-radius:10px; margin-bottom:13px; padding:15px; }.ctw-grant header { display:flex; gap:10px; align-items:start; }.ctw-grant header > div { flex:1; min-width:0; }.ctw-grant header strong { font-size:12px; font-weight:600; }.ctw-grant header p { color:var(--ctw-muted); font-size:10px; line-height:1.7; margin-top:4px; }.ctw-grant-icon { display:grid; place-items:center; width:30px; height:30px; border-radius:7px; background:var(--ctw-soft); color:var(--ctw-muted); flex-shrink:0; }.ctw-grant-icon svg { width:17px; height:17px; }
    .ctw-role-pills { display:flex; flex-wrap:wrap; gap:7px; margin-top:13px; }.ctw-role-pill { display:inline-flex; align-items:center; gap:10px; font-size:11px; color:var(--ctw-accent); background:color-mix(in srgb,var(--ctw-accent) 8%,var(--ctw-bg)); border:1px solid color-mix(in srgb,var(--ctw-accent) 18%,var(--ctw-border)); border-radius:7px; padding:5px 8px; }.ctw-role-pill button { display:grid; place-items:center; padding:2px; border-radius:4px; }.ctw-role-pill button:hover { background:color-mix(in srgb,var(--ctw-accent) 10%,var(--ctw-bg)); }.ctw-role-pill svg { width:13px; height:13px; }
    .ctw-detail-actions { display:flex; flex-wrap:wrap; gap:10px; margin-top:20px; }.ctw-detail-footer { display:flex; align-items:center; justify-content:space-between; gap:15px; margin-top:24px; border-top:1px solid var(--ctw-border); padding-top:18px; }.ctw-detail-footer p { color:var(--ctw-muted); font-size:10px; line-height:1.7; }.ctw-detail-footer strong { font-size:11px; }.ctw-danger-link { color:#dc2626; font-size:10px; background:transparent; white-space:nowrap; }.dark .ctw-danger-link { color:#fca5a5; }
    .ctw-empty { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:10px; padding:45px 24px; text-align:center; color:var(--ctw-muted); min-height:220px; }.ctw-empty > svg { width:28px; height:28px; }.ctw-empty strong { font-size:13px; color:var(--ctw-text); }.ctw-empty p { font-size:11px; line-height:1.8; max-width:400px; }.ctw-empty.is-compact { min-height:130px; padding:23px 15px; background:var(--ctw-soft); border-radius:10px; }.ctw-empty-wide { grid-column:1 / -1; border:1px dashed var(--ctw-border); border-radius:12px; }
    .ctw-module-summary { border:1px solid var(--ctw-border); border-radius:9px; margin-bottom:8px; }.ctw-module-summary summary { display:flex; align-items:center; gap:12px; cursor:pointer; padding:12px 14px; list-style:none; }.ctw-module-summary summary::-webkit-details-marker { display:none; }.ctw-module-summary summary > span:first-child { flex:1; }.ctw-module-summary small { display:block; color:var(--ctw-muted); font-size:9px; margin-bottom:2px; }.ctw-module-summary strong { font-size:12px; font-weight:600; }.ctw-module-summary summary > svg { width:14px; height:14px; color:var(--ctw-muted); }.ctw-module-summary[open] summary > svg { transform:rotate(180deg); }.ctw-module-summary dl { padding:0 14px 10px; }.ctw-module-summary dl > div { display:flex; justify-content:space-between; gap:10px; font-size:11px; padding:7px 0; border-top:1px solid var(--ctw-border); }.ctw-module-summary dd { color:var(--ctw-muted); text-align:right; }
    .ctw-cards { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }.ctw-card { padding:22px; background:var(--ctw-bg); border:1px solid var(--ctw-border); border-radius:12px; }.ctw-card h3 { font-size:16px; }.ctw-card > .ctw-muted { margin-top:4px; font-size:11px; overflow-wrap:anywhere; }.ctw-card-metrics { display:grid; grid-template-columns:1fr 1fr; gap:15px; margin:20px 0; padding:14px; background:var(--ctw-soft); border-radius:9px; }.ctw-card-metrics strong { display:block; font-size:14px; }.ctw-card-metrics span { display:block; color:var(--ctw-muted); font-size:10px; margin-top:4px; }.ctw-card-actions { display:flex; justify-content:space-between; align-items:center; gap:12px; margin-top:20px; border-top:1px solid var(--ctw-border); padding-top:16px; }
    .ctw-invitations { background:var(--ctw-bg); border:1px solid var(--ctw-border); border-radius:12px; overflow:hidden; }.ctw-invitation { display:flex; align-items:center; gap:15px; padding:20px; border-bottom:1px solid var(--ctw-border); }.ctw-invitation:last-child { border:0; }.ctw-invitation-main { flex:1; min-width:0; }.ctw-invitation-main strong { font-size:12px; overflow-wrap:anywhere; }.ctw-invitation-main p { color:var(--ctw-muted); font-size:11px; margin-top:4px; }.ctw-invitation-main small { display:block; color:var(--ctw-muted); font-size:10px; margin-top:4px; }
    .ctw-muted { color:var(--ctw-muted); }.ctw-sr-only { position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0; }
    @media (max-width:900px) { .ctw-intro { align-items:start; flex-direction:column; }.ctw-workspace { grid-template-columns:minmax(220px,.8fr) minmax(0,1.2fr); }.ctw-detail { padding:18px; }.ctw-section-heading { align-items:start; flex-direction:column; }.ctw-invitation { flex-wrap:wrap; }.ctw-invitation .ctw-actions { margin-left:51px; }.ctw-intro .ctw-actions { width:100%; } }
    @media (max-width:640px) { .ctw-workspace { grid-template-columns:1fr; }.ctw-list { max-height:260px; border-right:0; border-bottom:1px solid var(--ctw-border); }.ctw-list-item { padding:12px; }.ctw-detail { padding:17px; }.ctw-tabs { gap:0; }.ctw-tab { padding:12px 10px; font-size:11px; }.ctw-tab svg { display:none; }.ctw-detail-heading { flex-wrap:wrap; }.ctw-cards { grid-template-columns:1fr; }.ctw-detail-footer { align-items:start; flex-direction:column; }.ctw-notice { flex-wrap:wrap; }.ctw-notice > .ctw-outline-button { margin-left:28px; }.ctw-grant { padding:12px; }.ctw-grant header { flex-wrap:wrap; }.ctw-grant header > .fi-btn { margin-left:40px; }.ctw-invitation { padding:15px; gap:10px; }.ctw-invitation .ctw-actions { margin-left:0; }.ctw-card { padding:17px; } }
</style>
